using System;using System.Collections.Generic;using System.Diagnostics;using System.IO;using System.Linq;using System.Security.Cryptography;using System.Text;using System.Text.RegularExpressions;using System.Threading;using System.Threading.Tasks;using System.Web.Script.Serialization;
namespace ClearDisk {
 internal enum AdministrationKind {Drivers,RestorePoints,Pagefile,Software,Packages,PackageVolumes}
 internal enum AdministrationAction {DeleteDriver,DeleteRestorePoint,CreateRestorePoint,ConfigurePagefile,RestorePagefile,UninstallSoftware,MovePackage}
 internal sealed class AdministrationRecord {
  public string Id,Name,Reason;public bool Eligible;public Dictionary<string,string> Fields=new Dictionary<string,string>();
  internal string Fingerprint{get{var text=Id+"\n"+Name+"\n"+Eligible+"\n"+String.Join("\n",Fields.OrderBy(p=>p.Key,StringComparer.Ordinal).Select(p=>p.Key+"="+p.Value));using(var hash=SHA256.Create())return Convert.ToBase64String(hash.ComputeHash(Encoding.UTF8.GetBytes(text)));}}
  internal AdministrationRecord Copy(){return new AdministrationRecord{Id=Id,Name=Name,Eligible=Eligible,Reason=Reason,Fields=new Dictionary<string,string>(Fields)};}
 }
 internal sealed class AdministrationResult {internal readonly int ExitCode;internal readonly string Output,Error;internal bool Success{get{return ExitCode==0||ExitCode==3010;}}internal AdministrationResult(int code,string output,string error){ExitCode=code;Output=output;Error=error;}}
 internal interface IAdministrationBackend {AdministrationRecord[] Read(AdministrationKind kind,CancellationToken token);AdministrationResult Execute(AdministrationAction action,AdministrationRecord record,Dictionary<string,string> parameters);}
 internal sealed class AdministrationPlan {
  internal readonly AdministrationAction Action;internal readonly string Context,RecordFingerprint;internal readonly DateTime Expires;internal readonly AdministrationKind Kind;internal readonly string Description;
  readonly AdministrationRecord record;readonly Dictionary<string,string> parameters;
  internal AdministrationRecord Record{get{return record.Copy();}}internal Dictionary<string,string> Parameters{get{return new Dictionary<string,string>(parameters);}}
  internal AdministrationPlan(AdministrationAction action,AdministrationKind kind,AdministrationRecord item,Dictionary<string,string> args,string context,DateTime expiry,string description){Action=action;Kind=kind;record=item.Copy();RecordFingerprint=item.Fingerprint;parameters=new Dictionary<string,string>(args);Context=context;Expires=expiry;Description=description;}
 }
 internal sealed class AdvancedAdministrationEngine {
  readonly AdministrationConfigurationStore configurations;internal AdministrationConfigurationStore Configurations{get{return configurations;}}
  readonly IAdministrationBackend backend;readonly Func<string> context;readonly Func<bool> administrator;readonly Func<DateTime> clock;readonly HashSet<AdministrationPlan> issued=new HashSet<AdministrationPlan>();
  internal AdvancedAdministrationEngine():this(new WindowsAdministrationBackend(),CompatibleCleanupEngine.CurrentContext,()=>CompatibleCleanupEngine.CurrentContext().EndsWith(":True",StringComparison.Ordinal),()=>DateTime.UtcNow,new AdministrationConfigurationStore()){}
  internal AdvancedAdministrationEngine(IAdministrationBackend source,Func<string> identity,Func<bool> admin,Func<DateTime> time,AdministrationConfigurationStore backups=null){backend=source;context=identity;administrator=admin;clock=time;configurations=backups;}
  internal AdministrationRecord[] Read(AdministrationKind kind,CancellationToken token){issued.Clear();var list=backend.Read(kind,token);if(list==null||list.Length>20000||list.Any(r=>r==null||String.IsNullOrWhiteSpace(r.Id))||list.Select(r=>r.Id).Distinct(StringComparer.Ordinal).Count()!=list.Length)throw new IOException("系统库存不完整或身份重复，不能操作。");return list.Select(r=>r.Copy()).ToArray();}
  static AdministrationKind Kind(AdministrationAction action){switch(action){case AdministrationAction.DeleteDriver:return AdministrationKind.Drivers;case AdministrationAction.DeleteRestorePoint:case AdministrationAction.CreateRestorePoint:return AdministrationKind.RestorePoints;case AdministrationAction.ConfigurePagefile:case AdministrationAction.RestorePagefile:return AdministrationKind.Pagefile;case AdministrationAction.UninstallSoftware:return AdministrationKind.Software;case AdministrationAction.MovePackage:return AdministrationKind.Packages;default:throw new ArgumentException();}}
  internal static bool ContainsCSetting(string json){var entries=new JavaScriptSerializer().Deserialize<Dictionary<string,object>[]>(json);if(entries==null)throw new IOException("分页配置记录无效。");return entries.Any(item=>item.ContainsKey("Name")&&String.Equals(Convert.ToString(item["Name"]),@"C:\pagefile.sys",StringComparison.OrdinalIgnoreCase));}
  internal AdministrationPlan Preview(AdministrationAction action,string id,Dictionary<string,string> parameters,CancellationToken token){
   issued.Clear();var kind=Kind(action);var args=parameters==null?new Dictionary<string,string>():new Dictionary<string,string>(parameters);var items=Read(kind,token);var item=items.SingleOrDefault(r=>r.Id==id);
   if(action==AdministrationAction.CreateRestorePoint)item=new AdministrationRecord{Id="create",Name="创建系统还原点",Eligible=true};
   if(item==null||!item.Eligible)throw new IOException(item==null?"所选项目不存在，请重新查询。":item.Reason);
   string impact;
   switch(action){
    case AdministrationAction.DeleteDriver:if(!Regex.IsMatch(item.Id,@"\Aoem[0-9]+\.inf\z",RegexOptions.IgnoreCase))throw new IOException("驱动包标识无效。");impact="仅移除所选第三方驱动包；不使用强制、卸载在用设备或重启参数。在用包由 Windows 拒绝；此操作不可直接撤销。";break;
    case AdministrationAction.DeleteRestorePoint:if(!Regex.IsMatch(item.Id,@"\A[0-9]+\z")||item.Id==items.OrderByDescending(r=>UInt32.Parse(r.Id)).First().Id)throw new IOException("保留最新还原点；请选择较早的还原点。");impact="永久删除所选还原点；不会删除其他 VSS 备份，删除后不能恢复该还原点。";break;
    case AdministrationAction.CreateRestorePoint:impact="请求 Windows 创建系统还原点。系统保护未启用、策略或创建频率限制可能导致失败；成功不代表所有个人文件已备份。";break;
    case AdministrationAction.ConfigurePagefile:
     string drive;int initial,maximum;if(!args.TryGetValue("Drive",out drive)||!Regex.IsMatch(drive,@"\A[D-Z]:\\\z",RegexOptions.IgnoreCase)||!args.ContainsKey("InitialMB")||!args.ContainsKey("MaximumMB")||!Int32.TryParse(args["InitialMB"],out initial)||!Int32.TryParse(args["MaximumMB"],out maximum)||initial<16||maximum<initial||maximum>1048576)throw new IOException("请选择非 C 固定卷及 16–1048576 MB 的有效大小。");
     if(args.Keys.Any(k=>!new[]{"Drive","InitialMB","MaximumMB","RemoveC"}.Contains(k)))throw new IOException("分页配置包含未知字段。");
     if(!args.ContainsKey("RemoveC"))args["RemoveC"]="False";if(args["RemoveC"]!="True"&&args["RemoveC"]!="False")throw new IOException("迁移选项无效。");
     if(args["RemoveC"]=="True"&&(!item.Fields.ContainsKey("CrashDumpEnabled")||item.Fields["CrashDumpEnabled"]!="0"))throw new IOException("当前崩溃转储需要保留 C 盘分页配置；可添加目标卷分页文件并保留 C 配置。");
     impact="先保存原配置，再创建并核验目标分页配置。"+(args["RemoveC"]=="True"?"随后移除 C 盘分页配置。":"保留 C 盘分页配置以支持崩溃转储。")+"不会直接删除 pagefile.sys；需重启生效，不保证立即释放空间。失败将尝试恢复原配置并报告结果。";break;
    case AdministrationAction.RestorePagefile:
     if(configurations==null||args.Count!=1||!args.ContainsKey("BackupId"))throw new IOException("请选择本工具保存的配置备份。");var prior=configurations.Read(args["BackupId"]);args["RestoreAutomatic"]=prior.Fields["Automatic"];args["RestoreSettings"]=prior.Fields["Settings"];if(args["RestoreAutomatic"]!="True"&&item.Fields["CrashDumpEnabled"]!="0"&&!ContainsCSetting(args["RestoreSettings"]))throw new IOException("当前转储策略已变化，拒绝恢复缺少 C 盘分页文件的配置。");impact="恢复所选备份中的全部分页配置（包含涉及的其他卷）；当前配置会先备份。需要重启生效，不删除任何分页文件。";break;
    case AdministrationAction.UninstallSoftware:impact="启动登记的软件卸载程序；可能出现厂商窗口。卸载不能由本工具撤销；不会强删软件目录。不自动重启。";break;
    case AdministrationAction.MovePackage:
     if(args.Count!=1||!args.ContainsKey("Volume"))throw new IOException("请选择已登记的应用目标卷。");var volumes=backend.Read(AdministrationKind.PackageVolumes,token);var volume=volumes.SingleOrDefault(v=>v.Id==args["Volume"]&&v.Eligible);if(volume==null)throw new IOException("应用目标卷不可用。");string installation,storePath;if(item.Fields.TryGetValue("InstallLocation",out installation)&&volume.Fields.TryGetValue("PackageStorePath",out storePath)&&!String.IsNullOrEmpty(storePath)&&(String.Equals(installation,storePath,StringComparison.OrdinalIgnoreCase)||installation.StartsWith(storePath.TrimEnd('\\')+"\\",StringComparison.OrdinalIgnoreCase)))throw new IOException("所选应用已经位于该应用卷，请选择其他已登记卷。");args["VolumeFingerprint"]=volume.Fingerprint;args["VolumeStorePath"]=volume.Fields.ContainsKey("PackageStorePath")?volume.Fields["PackageStorePath"]:"";impact="使用 Windows Move-AppxPackage 移动当前用户所选 MSIX/Appx 应用；可能需关闭应用。再次选择原应用卷可迁回。传统 Win32 软件需厂商迁移方式或卸载后重装。";break;
    default:throw new ArgumentException();
   }
   if(action!=AdministrationAction.ConfigurePagefile&&action!=AdministrationAction.RestorePagefile&&action!=AdministrationAction.MovePackage&&args.Count!=0)throw new IOException("该操作不接受额外参数。");
   var plan=new AdministrationPlan(action,kind,item,args,context(),clock().AddMinutes(10),item.Name+"\r\n"+impact+"\r\n"+String.Join("\r\n",args.Select(p=>p.Key+": "+p.Value)));issued.Add(plan);return plan;
  }
  internal AdministrationResult Execute(AdministrationPlan plan,bool confirmed,CancellationToken token){
   if(!confirmed)throw new InvalidOperationException("请先确认具体预览。");if(plan==null||!issued.Remove(plan)||clock()>plan.Expires||plan.Context!=context()||!administrator())throw new InvalidOperationException("预览失效或需要管理员权限；请在管理员窗口重新预览。");
   token.ThrowIfCancellationRequested();if(plan.Action!=AdministrationAction.CreateRestorePoint){var current=backend.Read(plan.Kind,token).SingleOrDefault(r=>r.Id==plan.Record.Id);if(current==null||!current.Eligible||current.Fingerprint!=plan.RecordFingerprint)throw new IOException("所选项目自预览后变化，拒绝执行。");}
   if(plan.Action==AdministrationAction.DeleteRestorePoint){var items=backend.Read(plan.Kind,token);if(items.OrderByDescending(r=>UInt32.Parse(r.Id)).First().Id==plan.Record.Id)throw new IOException("不能删除最新还原点。");}
   if(plan.Action==AdministrationAction.MovePackage){var volume=backend.Read(AdministrationKind.PackageVolumes,token).SingleOrDefault(r=>r.Id==plan.Parameters["Volume"]);if(volume==null||!volume.Eligible||volume.Fingerprint!=plan.Parameters["VolumeFingerprint"])throw new IOException("目标应用卷已变化。");}
   if(context()!=plan.Context)throw new IOException("执行前权限发生变化。");string backup=null;if(configurations!=null&&(plan.Action==AdministrationAction.ConfigurePagefile||plan.Action==AdministrationAction.RestorePagefile))backup=configurations.Save(plan.Record);var result=backend.Execute(plan.Action,plan.Record,plan.Parameters);return backup==null?result:new AdministrationResult(result.ExitCode,result.Output+"\r\n变更前配置备份："+backup,result.Error);
  }
 }
 internal sealed class WindowsAdministrationBackend:IAdministrationBackend {
  static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=16777216};
  internal static AdministrationResult Run(string script,CancellationToken token,bool cancellable){
   string executable=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"WindowsPowerShell","v1.0","powershell.exe");
   var psi=new ProcessStartInfo(executable,"-NoLogo -NoProfile -NonInteractive -EncodedCommand "+Convert.ToBase64String(Encoding.Unicode.GetBytes("$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=New-Object Text.UTF8Encoding($false);try {"+script+"} catch { [Console]::Error.WriteLine($_.Exception.Message); exit 1 }"))){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.UTF8,StandardErrorEncoding=Encoding.UTF8};
   psi.EnvironmentVariables["PSModulePath"]=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"WindowsPowerShell","v1.0","Modules");psi.EnvironmentVariables["WINDIR"]=Environment.GetFolderPath(Environment.SpecialFolder.Windows);psi.EnvironmentVariables["SystemRoot"]=Environment.GetFolderPath(Environment.SpecialFolder.Windows);
   using(var process=new Process{StartInfo=psi}){token.ThrowIfCancellationRequested();process.Start();var stdout=Task.Factory.StartNew(()=>Bounded(process.StandardOutput),TaskCreationOptions.LongRunning);var stderr=Task.Factory.StartNew(()=>Bounded(process.StandardError),TaskCreationOptions.LongRunning);while(!process.WaitForExit(100)){if(cancellable&&token.IsCancellationRequested){process.Kill();process.WaitForExit();Task.WaitAll(stdout,stderr);token.ThrowIfCancellationRequested();}}Task.WaitAll(stdout,stderr);return new AdministrationResult(process.ExitCode,stdout.Result,stderr.Result);}
  }
  static string Bounded(TextReader reader){var value=new StringBuilder();char[] buffer=new char[4096];int n;bool exceeded=false;while((n=reader.Read(buffer,0,buffer.Length))>0){if(value.Length+n>8388608){exceeded=true;continue;}value.Append(buffer,0,n);}if(exceeded)throw new IOException("库存/日志超出上限，不能当成完整结果。");return value.ToString();}
  internal static string ReadScript(AdministrationKind kind){switch(kind){
   case AdministrationKind.Drivers:return @"Import-Module Dism; $used=@(Get-CimInstance Win32_PnPSignedDriver | ForEach-Object { $_.InfName }); Get-WindowsDriver -Online | ForEach-Object { $ok=(-not $_.Inbox -and -not $_.BootCritical -and $used -notcontains $_.Driver); [pscustomobject]@{Id=[string]$_.Driver;Name=([string]$_.ProviderName+' / '+[string]$_.OriginalFileName);Eligible=$ok;Reason='仅未被设备登记使用的第三方包可尝试移除；Windows仍会核验是否在用';Fields=@{Version=[string]$_.Version;Date=$_.Date.ToUniversalTime().ToString('o');Original=[string]$_.OriginalFileName;Provider=[string]$_.ProviderName;BootCritical=[string]$_.BootCritical;Inbox=[string]$_.Inbox;InUse=[string]($used -contains $_.Driver)}} }";
   case AdministrationKind.RestorePoints:return @"Get-CimInstance -Namespace root/default -ClassName SystemRestore | ForEach-Object { [pscustomobject]@{Id=[string]$_.SequenceNumber;Name=[string]$_.Description;Eligible=$true;Reason='保留最新还原点，其他点需逐项确认';Fields=@{CreationTime=[string]$_.CreationTime;RestorePointType=[string]$_.RestorePointType}} }";
   case AdministrationKind.Pagefile:return @"$computer=Get-CimInstance Win32_ComputerSystem; $settings=@(Get-CimInstance Win32_PageFileSetting | Sort-Object Name | Select-Object Name,InitialSize,MaximumSize); $dump=Get-ItemProperty -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Control\CrashControl'; [pscustomobject]@{Id='pagefile-config';Name='分页文件配置';Eligible=$true;Reason='配置需重启生效';Fields=@{Automatic=[string]$computer.AutomaticManagedPagefile;Settings=ConvertTo-Json -InputObject $settings -Compress;CrashDumpEnabled=[string]$dump.CrashDumpEnabled;DedicatedDumpFile=[string]$dump.DedicatedDumpFile}}";
   case AdministrationKind.Software:return SoftwareInventoryScript;
   case AdministrationKind.Packages:return @"Import-Module Appx; Get-AppxPackage | Where-Object { -not $_.IsFramework -and -not $_.IsResourcePackage } | ForEach-Object { [pscustomobject]@{Id=[string]$_.PackageFullName;Name=[string]$_.Name;Eligible=(-not $_.NonRemovable -and -not $_.IsDevelopmentMode);Reason='仅Windows支持移动的当前用户MSIX/Appx应用，系统应用不支持';Fields=@{InstallLocation=[string]$_.InstallLocation;Version=[string]$_.Version;PublisherId=[string]$_.PublisherId;Status=[string]$_.Status}} }";
   case AdministrationKind.PackageVolumes:return @"Import-Module Appx; Get-AppxVolume | Where-Object { -not $_.IsOffline } | ForEach-Object { [pscustomobject]@{Id=[string]$_.Name;Name=[string]$_.PackageStorePath;Eligible=$true;Reason='已登记应用卷';Fields=@{PackageStorePath=[string]$_.PackageStorePath;IsSystemVolume=[string]$_.IsSystemVolume}} }";
   default:throw new ArgumentException();}}
  const string SoftwareInventoryScript=@"foreach($hive in @('CurrentUser','LocalMachine')) { foreach($view in @('Registry32','Registry64')) { if(-not [Environment]::Is64BitOperatingSystem -and $view -eq 'Registry64'){continue}; $base=[Microsoft.Win32.RegistryKey]::OpenBaseKey([Microsoft.Win32.RegistryHive]::$hive,[Microsoft.Win32.RegistryView]::$view); try { $root=$base.OpenSubKey('Software\Microsoft\Windows\CurrentVersion\Uninstall'); if($null -eq $root){continue}; try { foreach($name in $root.GetSubKeyNames()) { $key=$root.OpenSubKey($name); try { $display=[string]$key.GetValue('DisplayName'); if(-not $display){continue}; $raw=[string]$key.GetValue('UninstallString'); $location=[Environment]::ExpandEnvironmentVariables([string]$key.GetValue('InstallLocation')); $msi=([int]$key.GetValue('WindowsInstaller',0) -eq 1 -and $name -match '^\{[0-9A-Fa-f-]{36}\}$'); $exe='';$arguments='';$hash='';if(-not $msi -and $raw -match '^\s*(?:""([^""]+\.exe)""|([^\s""]+\.exe))(?:\s+(.*))?$'){ $exe=[Environment]::ExpandEnvironmentVariables(($matches[1]+$matches[2]));$arguments=[string]$matches[3];if([IO.Path]::IsPathRooted($exe) -and $location -and $exe.StartsWith($location.TrimEnd('\')+'\',[StringComparison]::OrdinalIgnoreCase) -and (Test-Path -LiteralPath $exe -PathType Leaf)){ $canonicalExe=[IO.Path]::GetFullPath($exe);$canonicalRoot=[IO.Path]::GetFullPath($location).TrimEnd('\');$ordinary=$canonicalExe.StartsWith($canonicalRoot+'\',[StringComparison]::OrdinalIgnoreCase);$walk=$canonicalExe;while($walk -and $walk.Length -gt 3){if(([IO.File]::GetAttributes($walk) -band [IO.FileAttributes]::ReparsePoint) -ne 0){$ordinary=$false;break};$walk=[IO.Path]::GetDirectoryName($walk)};$blocked=@('cmd.exe','powershell.exe','pwsh.exe','wscript.exe','cscript.exe','rundll32.exe','regsvr32.exe','mshta.exe','msbuild.exe','installutil.exe','reg.exe','conhost.exe');$programRoots=@([Environment]::GetFolderPath('ProgramFiles'),[Environment]::GetFolderPath('ProgramFilesX86'))|Where-Object {$_};$trustedRoot=@($programRoots|Where-Object {$canonicalRoot.StartsWith($_.TrimEnd('\')+'\',[StringComparison]::OrdinalIgnoreCase)}).Count -gt 0;if($ordinary -and $trustedRoot -and $hive -eq 'LocalMachine' -and $blocked -notcontains [IO.Path]::GetFileName($canonicalExe) -and (Get-AuthenticodeSignature -LiteralPath $canonicalExe).Status -eq 'Valid'){$exe=$canonicalExe;$location=$canonicalRoot;$hash=(Get-FileHash -LiteralPath $canonicalExe -Algorithm SHA256).Hash} } }; $ok=($key.GetValue('NoRemove',0) -ne 1 -and $key.GetValue('SystemComponent',0) -ne 1 -and ($msi -or $hash));[pscustomobject]@{Id=($hive+'/'+$view+'/'+$name);Name=$display;Eligible=[bool]$ok;Reason='支持有效MSI登记或Program Files内有效签名的HKLM厂商EXE；其他项目请用Windows应用设置';Fields=@{Hive=$hive;View=$view;Subkey=$name;RawCommand=$raw;Location=$location;MSI=[string]$msi;Exe=$exe;Arguments=$arguments;Hash=$hash;Version=[string]$key.GetValue('DisplayVersion')}} } finally { if($key){$key.Dispose()} } } } finally {$root.Dispose()} } finally {$base.Dispose()} } }";
  public AdministrationRecord[] Read(AdministrationKind kind,CancellationToken token){var result=Run("[Console]::OutputEncoding=New-Object Text.UTF8Encoding($false);$items=@(& {"+ReadScript(kind)+"});ConvertTo-Json -InputObject $items -Depth 6 -Compress",token,true);if(!result.Success||!String.IsNullOrWhiteSpace(result.Error))throw new IOException("读取系统库存失败："+result.Error);try{return Json.Deserialize<AdministrationRecord[]>(result.Output)??new AdministrationRecord[0];}catch(Exception e){throw new IOException("系统返回无法验证的库存。",e);}}
  internal static string CommandScript(AdministrationAction action,AdministrationRecord record,Dictionary<string,string> parameters){
   string data=Convert.ToBase64String(Encoding.UTF8.GetBytes(Json.Serialize(new{Record=record,Parameters=parameters})));string script="[Console]::OutputEncoding=New-Object Text.UTF8Encoding($false);$data=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('"+data+"'))|ConvertFrom-Json;$wanted=$data.Record;$argsMap=$data.Parameters;";
   AdministrationKind kind=action==AdministrationAction.DeleteDriver?AdministrationKind.Drivers:action==AdministrationAction.DeleteRestorePoint||action==AdministrationAction.CreateRestorePoint?AdministrationKind.RestorePoints:action==AdministrationAction.ConfigurePagefile||action==AdministrationAction.RestorePagefile?AdministrationKind.Pagefile:action==AdministrationAction.UninstallSoftware?AdministrationKind.Software:AdministrationKind.Packages;
   if(action!=AdministrationAction.CreateRestorePoint)script+="$records=@(& {"+ReadScript(kind)+"});$current=@($records|Where-Object {$_.Id -ceq $wanted.Id});if($current.Count -ne 1 -or -not $current[0].Eligible){throw '项目状态已变化'};foreach($property in $wanted.Fields.PSObject.Properties){if([string]$current[0].Fields[$property.Name] -cne [string]$property.Value){throw '项目字段已变化，拒绝执行'}};";
   switch(action){
    case AdministrationAction.DeleteDriver:return script+@"if($wanted.Id -notmatch '^oem[0-9]+\.inf$'){throw '无效INF'};& (Join-Path $env:WINDIR 'System32\pnputil.exe') /delete-driver $wanted.Id;exit $LASTEXITCODE;";
    case AdministrationAction.CreateRestorePoint:return script+"$result=Invoke-CimMethod -Namespace root/default -ClassName SystemRestore -MethodName CreateRestorePoint -Arguments @{Description='CDriveCleaner manual restore point';RestorePointType=[uint32]12;EventType=[uint32]100};if($result.ReturnValue -ne 0){throw ('创建失败: '+$result.ReturnValue)};'已请求创建还原点，请刷新核对';";
    case AdministrationAction.DeleteRestorePoint:return script+RestoreRemovalScript;
    case AdministrationAction.ConfigurePagefile:return script+PagefileScript;
    case AdministrationAction.RestorePagefile:return script+RestorePagefileScript;
    case AdministrationAction.UninstallSoftware:return script+@"if($wanted.Fields.MSI -ceq 'True'){if($wanted.Fields.Subkey -notmatch '^\{[0-9A-Fa-f-]{36}\}$'){throw 'MSI身份无效'};$exe=Join-Path $env:WINDIR 'System32\msiexec.exe';$arguments='/x '+$wanted.Fields.Subkey+' /norestart'}else{$exe=$wanted.Fields.Exe;$arguments=$wanted.Fields.Arguments;if((Get-FileHash -LiteralPath $exe -Algorithm SHA256).Hash -cne $wanted.Fields.Hash){throw '卸载程序内容已变化'}};$start=New-Object Diagnostics.ProcessStartInfo;$start.FileName=$exe;$start.Arguments=$arguments;$start.UseShellExecute=$false;$process=[Diagnostics.Process]::Start($start);$process.WaitForExit();exit $process.ExitCode;";
    case AdministrationAction.MovePackage:return script+"Import-Module Appx;$volume=@(Get-AppxVolume|Where-Object {$_.Name -ceq $argsMap.Volume -and -not $_.IsOffline});if($volume.Count -ne 1){throw '应用卷不可用'};Move-AppxPackage -Package $wanted.Id -Volume $volume[0] -ErrorAction Stop;'Windows应用移动已完成；刷新核对安装位置';";
    default:throw new ArgumentException();}
  }
  const string RestoreRemovalScript=@"$latest=$records|Sort-Object {[uint32]$_.Id} -Descending|Select-Object -First 1;if($latest.Id -eq $wanted.Id){throw '不能删除最新还原点'};Add-Type -TypeDefinition 'using System;using System.Runtime.InteropServices;public static class CDriveRestoreApi{[DllImport(""kernel32.dll"",CharSet=CharSet.Unicode,SetLastError=true)]static extern IntPtr LoadLibraryEx(string p,IntPtr f,uint flags);[DllImport(""kernel32.dll"",CharSet=CharSet.Ansi,SetLastError=true)]static extern IntPtr GetProcAddress(IntPtr m,string n);[DllImport(""kernel32.dll"")]static extern bool FreeLibrary(IntPtr m);[UnmanagedFunctionPointer(CallingConvention.Winapi)]delegate uint Remove(uint sequence);public static uint Run(uint sequence){var m=LoadLibraryEx(System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),""SrClient.dll""),IntPtr.Zero,0x800);if(m==IntPtr.Zero)throw new System.ComponentModel.Win32Exception();try{var p=GetProcAddress(m,""SRRemoveRestorePoint"");if(p==IntPtr.Zero)throw new System.ComponentModel.Win32Exception();return ((Remove)Marshal.GetDelegateForFunctionPointer(p,typeof(Remove)))(sequence);}finally{FreeLibrary(m);}}}';$code=[CDriveRestoreApi]::Run([uint32]$wanted.Id);if($code -ne 0){throw ('删除失败: '+$code)};'所选还原点已删除';";
  const string PagefileScript=@"$drive=[string]$argsMap.Drive;if($drive -notmatch '^[D-Z]:\\$'){throw '目标卷无效'};$disk=Get-CimInstance Win32_LogicalDisk|Where-Object {$_.DeviceID -eq $drive.Substring(0,2)};if($null -eq $disk -or $disk.DriveType -ne 3 -or $disk.FileSystem -ne 'NTFS' -or [uint64]$disk.FreeSpace -lt ([uint64]$argsMap.MaximumMB*1MB+256MB)){throw '目标需有足够空间的固定NTFS卷'};$initial=[uint32]$argsMap.InitialMB;$maximum=[uint32]$argsMap.MaximumMB;if($initial -lt 16 -or $maximum -lt $initial -or $maximum -gt 1048576){throw '大小无效'};if($argsMap.RemoveC -ceq 'True' -and $wanted.Fields.CrashDumpEnabled -ne '0'){throw '崩溃转储需要保留C盘分页配置'};[array]$old=ConvertFrom-Json -InputObject ([string]$wanted.Fields.Settings);$computer=Get-CimInstance Win32_ComputerSystem;$target=$drive+'pagefile.sys';$existing=@(Get-CimInstance Win32_PageFileSetting|Where-Object {$_.Name -ieq $target});$createdC=$false;try{Set-CimInstance -InputObject $computer -Property @{AutomaticManagedPagefile=$false}|Out-Null;if($argsMap.RemoveC -cne 'True'){$boot=@(Get-CimInstance Win32_PageFileSetting|Where-Object {$_.Name -ieq 'C:\pagefile.sys'});if($boot.Count -eq 0){New-CimInstance -ClassName Win32_PageFileSetting -Property @{Name='C:\pagefile.sys';InitialSize=[uint32]0;MaximumSize=[uint32]0}|Out-Null;$createdC=$true};$boot=@(Get-CimInstance Win32_PageFileSetting|Where-Object {$_.Name -ieq 'C:\pagefile.sys'});if($boot.Count -ne 1){throw 'C盘分页配置保留验证失败'}};if($existing.Count){Set-CimInstance -InputObject $existing[0] -Property @{InitialSize=$initial;MaximumSize=$maximum}|Out-Null}else{New-CimInstance -ClassName Win32_PageFileSetting -Property @{Name=$target;InitialSize=$initial;MaximumSize=$maximum}|Out-Null};$verify=@(Get-CimInstance Win32_PageFileSetting|Where-Object {$_.Name -ieq $target -and $_.InitialSize -eq $initial -and $_.MaximumSize -eq $maximum});if($verify.Count -ne 1){throw '目标配置验证失败'};if($argsMap.RemoveC -ceq 'True'){Get-CimInstance Win32_PageFileSetting|Where-Object {$_.Name -ieq 'C:\pagefile.sys'}|Remove-CimInstance};'已保存目标分页配置，重启后生效';exit 3010}catch{$failure=$_;try{if($createdC -and -not ($old|Where-Object {$_.Name -ieq 'C:\pagefile.sys'})){Get-CimInstance Win32_PageFileSetting|Where-Object {$_.Name -ieq 'C:\pagefile.sys'}|Remove-CimInstance};if(-not ($old|Where-Object {$_.Name -ieq $target})){Get-CimInstance Win32_PageFileSetting|Where-Object {$_.Name -ieq $target}|Remove-CimInstance};foreach($setting in $old){$live=@(Get-CimInstance Win32_PageFileSetting|Where-Object {$_.Name -ieq $setting.Name});if($live.Count){Set-CimInstance -InputObject $live[0] -Property @{InitialSize=[uint32]$setting.InitialSize;MaximumSize=[uint32]$setting.MaximumSize}|Out-Null}else{New-CimInstance -ClassName Win32_PageFileSetting -Property @{Name=[string]$setting.Name;InitialSize=[uint32]$setting.InitialSize;MaximumSize=[uint32]$setting.MaximumSize}|Out-Null}};Set-CimInstance -InputObject (Get-CimInstance Win32_ComputerSystem) -Property @{AutomaticManagedPagefile=($wanted.Fields.Automatic -ceq 'True')}|Out-Null;[Console]::Error.WriteLine('变更失败，已尝试恢复先前配置；请刷新核对')}catch{[Console]::Error.WriteLine('配置补偿失败，请打开Windows虚拟内存设置核对')};throw $failure}";
  const string RestorePagefileScript=@"[array]$settings=ConvertFrom-Json -InputObject ([string]$argsMap.RestoreSettings);foreach($setting in $settings){if($setting.Name -notmatch '^[A-Z]:\\pagefile\.sys$' -or [uint32]$setting.MaximumSize -gt 1048576 -or [uint32]$setting.InitialSize -gt [uint32]$setting.MaximumSize){throw '备份配置无效'};$drive=([string]$setting.Name).Substring(0,2);$disk=@(Get-CimInstance Win32_LogicalDisk|Where-Object {$_.DeviceID -eq $drive -and $_.DriveType -eq 3});if($disk.Count -ne 1 -or $disk[0].FileSystem -ne 'NTFS' -or [uint64]$disk[0].FreeSpace -lt ([uint64]$setting.InitialSize*1MB+256MB)){throw '备份涉及的目标卷不可用或空间不足，尚未更改配置'}};[array]$before=ConvertFrom-Json -InputObject ([string]$wanted.Fields.Settings);function Apply-PagefileState($items,$automatic){Set-CimInstance -InputObject (Get-CimInstance Win32_ComputerSystem) -Property @{AutomaticManagedPagefile=$false}|Out-Null;foreach($setting in $items){$live=@(Get-CimInstance Win32_PageFileSetting|Where-Object {$_.Name -ieq $setting.Name});if($live.Count){Set-CimInstance -InputObject $live[0] -Property @{InitialSize=[uint32]$setting.InitialSize;MaximumSize=[uint32]$setting.MaximumSize}|Out-Null}else{New-CimInstance -ClassName Win32_PageFileSetting -Property @{Name=[string]$setting.Name;InitialSize=[uint32]$setting.InitialSize;MaximumSize=[uint32]$setting.MaximumSize}|Out-Null}};Get-CimInstance Win32_PageFileSetting|Where-Object {$items.Name -notcontains $_.Name}|Remove-CimInstance;Set-CimInstance -InputObject (Get-CimInstance Win32_ComputerSystem) -Property @{AutomaticManagedPagefile=$automatic}|Out-Null;if((Get-CimInstance Win32_ComputerSystem).AutomaticManagedPagefile -ne $automatic){throw '自动管理状态验证失败'};if(-not $automatic){$live=@(Get-CimInstance Win32_PageFileSetting);if($live.Count -ne $items.Count){throw '分页配置数量验证失败'};foreach($setting in $items){if(@($live|Where-Object {$_.Name -ieq $setting.Name -and $_.InitialSize -eq $setting.InitialSize -and $_.MaximumSize -eq $setting.MaximumSize}).Count -ne 1)