  public AdministrationResult Execute(AdministrationAction action,AdministrationRecord record,Dictionary<string,string> parameters){
   if(action==AdministrationAction.UninstallSoftware&&record.Fields.ContainsKey("MSI")&&record.Fields["MSI"]!="True"){
